# 전부 OX. (원본, 보기번호 or 0, 문장, 정답 O/X, 달라진 점, 해설, 근거)
from variants import V
P=[]
def a(o,s,t,ans,d,e,src): P.append(dict(of=o,slot=s,q=t,ans=ans,diff=d,exp=e,src=src))
# --- 4지선다 → 보기마다 OX
a(11,1,"투자상품 포트폴리오 구성방법 중 기대수익률 극대화 방법이 가장 많이 사용된다.","O","보기 그대로","원본 11번에서 옳은 보기다.","교재 1권 p.118")
a(11,2,"최적화 포트폴리오 방법은 지배원리(dominance frontier)를 활용한다.","O","보기 그대로","원본 11번에서 옳은 보기다.","교재 1권 p.118")
a(11,3,"핵심-위성 포트폴리오 방법은 선진국에서는 잘 사용하지 않는 방법이다.","X","원본의 틀린 보기 그대로","선진국에서 기본적으로 쓰는 방법이며, 전문가들은 핵심:위성 비중을 80:20으로 권한다.","교재 1권 p.118")
a(11,4,"모델 포트폴리오 방법은 고객의 특이한 상황을 쉽게 반영할 수 있다.","X","'반영하기 어렵다' → '쉽게 반영할 수 있다'","모델 포트폴리오 방법은 정해진 모델을 쓰기 때문에 고객의 특이한 상황을 반영하기 어렵다.","교재 1권 p.118")
a(14,1,"국내 펀드에서 발생하는 주식의 매매·평가차익은 과세된다.","X","'과세되지 않는다' → '과세된다'","펀드 소득 중 주식의 매매·평가차익만 과세하지 않고 나머지는 모두 과세한다.","교재 1권 p.187")
a(14,2,"펀드에서 발생하는 주식 배당소득은 과세대상 소득이다.","O","보기 그대로","주식 매매·평가차익을 뺀 나머지(주식배당, 채권 매매·평가차익, 채권이자)는 모두 과세한다.","교재 1권 p.187")
a(14,3,"펀드에서 발생하는 채권의 매매·평가차익은 과세되지 않는다.","X","원본의 틀린 보기 그대로","과세하지 않는 것은 주식의 매매·평가차익뿐이다. 채권 매매·평가차익은 과세한다.","교재 1권 p.187")
a(14,4,"펀드에서 발생하는 채권이자는 과세대상 소득이다.","O","보기 그대로","채권이자는 과세한다.","교재 1권 p.187")
a(16,1,"투자자정보 중 일부만 제공한 고객에게는 해당 고객이 제공한 정보의 범위 내에서 적합한 투자권유를 해야 한다.","O","보기 그대로","투자권유준칙 내용 그대로다.","교재 1권 p.293")
a(16,2,"적합성의 원칙은 '파생상품 등'과 관련한 판매에 있어서의 '특칙'으로 이해할 수 있다.","X","'적정성의 원칙' → '적합성의 원칙'","'파생상품 등' 판매의 특칙은 적정성의 원칙이다.","교재 1권 p.292")
a(16,3,"금융투자상품의 매매나 계약체결의 권유가 수반되지 않은 정보제공 등도 투자권유로 볼 수 있다.","X","원본의 틀린 보기 그대로","권유가 수반되지 않은 정보제공 등은 투자권유로 볼 수 없다.","교재 1권 p.293")
a(16,4,"집합투자증권을 적립식으로 10년 이상 투자할 경우 해당 상품의 위험도를 한 단계 하향하는 방법 등을 별도로 정해 제시할 수 있다.","O","보기 그대로","투자권유준칙 내용 그대로다.","교재 1권 p.293")
a(21,1,"추가형·단위형 구분은 펀드의 좌수를 추가로 설정할 수 있느냐에 따른 분류이다.","O","보기 그대로","교재 정의 그대로다.","교재 1권 p.62")
a(21,2,"개방형·폐쇄형 구분은 펀드의 좌수를 추가로 설정할 수 있느냐에 따른 분류이다.","X","'중도 환매 가능 여부' → '좌수 추가 설정 여부'","개방형·폐쇄형은 중도 환매를 가능하게 해주느냐에 따른 분류다. 좌수 추가 설정은 추가형·단위형의 기준이다.","교재 1권 p.63")
a(21,3,"주식형펀드는 펀드재산의 50% 이상을 주식에 투자하는 펀드를 말한다.","X","원본의 틀린 보기 그대로","주식형펀드는 펀드재산의 60% 이상을 주식에 투자한다.","교재 1권 p.64")
a(21,4,"증권형·파생형 구분은 펀드 자산의 일정 부분 이상을 파생상품에 투자할 수 있느냐에 따른 구분이다.","O","보기 그대로","원본 21번에서 옳은 보기다.","교재 1권 p.64")
a(22,1,"액티브 운용전략은 Bottom-up 접근방식과 Top-down 접근방식으로 크게 나눌 수 있다.","O","보기 그대로","원본 22번에서 옳은 보기다.","교재 1권 p.70")
a(22,2,"액티브 운용전략 펀드는 시스템 펀드로 표현될 수 있다.","X","원본의 틀린 보기 그대로","시스템 펀드는 패시브 운용전략에 대한 설명이다. 액티브 펀드의 목표는 인덱스+α다.","교재 1권 p.70")
a(22,3,"주식 운용에서 Bottom-up 접근방식은 투자대상 종목의 저평가 여부만을 투자 기준으로 판단한다.","O","보기 그대로","원본 22번에서 옳은 보기다.","교재 1권 p.70")
a(22,4,"Top-down 접근방식은 경제·금융 동향과 관계없이 개별 종목의 저평가 여부만으로 투자한다.","X","'경제·금융 동향에 따라 자산·업종 비율 조절' → '동향과 관계없이'","Top-down은 경제·금융 동향 변화에 따라 자산 간, 업종 간 투자비율을 탄력적으로 조절한다.","교재 1권 p.70")
a(23,1,"패시브운용 펀드는 체계적인 거래 기법을 이용하여 운용되는 펀드를 가리킨다.","O","보기 그대로","원본 23번에서 옳은 보기다.","교재 1권 p.70")
a(23,2,"패시브펀드의 예로 인덱스형, 시스템트레이드형 등을 들 수 있다.","O","보기 그대로","원본 23번에서 옳은 보기다.","교재 1권 p.70")
a(23,3,"패시브운용 펀드매니저는 비교대상 수익률을 크게 초과하는 것이 운용 목표이다.","X","원본의 틀린 보기 그대로","패시브운용은 비교대상 지수(인덱스)와 유사하거나 근접한 수익을 목표로 한다.","교재 1권 p.70")
a(23,4,"패시브펀드는 액티브로 운용하는 펀드보다 보수가 비싼 경우가 많다.","X","'저렴한 경우가 많다' → '비싼 경우가 많다'","패시브펀드는 매매회전율이 낮아 액티브 펀드보다 보수가 저렴한 경우가 많다.","교재 1권 p.70")
a(25,1,"ELS(주가연계증권)의 발행회사는 은행이다.","X","'증권사' → '은행'","ELS는 증권사(투자매매업자)가 발행한다. 은행이 발행하는 것은 ELD다.","교재 1권 p.100")
a(25,2,"ELS(주가연계증권)의 형태는 유가증권이다.","O","보기 그대로","ELS는 유가증권, ELF는 수익증권, ELD는 정기예금이다.","교재 1권 p.100")
a(25,3,"ELS(주가연계증권)는 5천만원까지 예금자보호가 된다.","X","원본의 틀린 보기 그대로","예금자보호는 ELD만 된다. ELS는 예금자보호가 되지 않는다.","교재 1권 p.100")
a(25,4,"ELS(주가연계증권)에서 발생한 소득은 배당소득으로 과세된다.","O","보기 그대로","원본 25번에서 옳은 보기다.","교재 1권 p.100")
a(35,1,"보험금액은 보험계약법상의 최고한도금액이다.","X","원본의 틀린 보기 그대로","보험금액은 보험계약상의 최고한도금액이다. 보험계약법상의 최고한도액은 보험가액이다.","교재 2권 p.32~33")
a(35,2,"보험가액은 보험계약의 목적에 대한 금전적 평가액이다.","O","틀린 보기를 맞게 고침","보험가액은 보험계약의 목적에 대한 금전적 평가액, 즉 발생할 수 있는 최대손해금액이다.","교재 2권 p.32~33")
a(35,3,"보험가액은 보험사고로 보험의 목적에 발생할 수 있는 최대손해금액이다.","O","보기 그대로","원본 35번의 정답 보기다.","교재 2권 p.32~33")
a(35,4,"보험가액이 보험금액보다 큰 경우를 초과보험이라고 한다.","X","원본의 틀린 보기 그대로","보험가액이 보험금액보다 큰 경우는 일부보험이다. 초과보험은 보험금액이 보험가액보다 큰 경우다.","교재 2권 p.33")
a(36,1,"금융기관보험대리점 등은 보험계약 체결을 대리할 때 그 계약의 주요 보장 내용을 설명해야 한다.","O","보기를 문장으로","설명의무 사항: 주요 보장 내용, 환급금, 불완전판매 방지를 위해 금융위가 고시하는 사항.","교재 2권 p.40")
a(36,2,"금융기관보험대리점 등은 보험계약 체결을 대리할 때 그 계약의 환급금을 설명해야 한다.","O","보기를 문장으로","환급금은 설명의무 사항이다.","교재 2권 p.40")
a(36,3,"금융기관보험대리점 등은 보험계약 체결을 대리할 때 모집수수료율을 보험계약자에게 설명해야 한다.","X","원본의 정답(설명사항 아님) 그대로","모집수수료율은 설명 사항이 아니라 점포 창구와 인터넷 홈페이지에 공시하는 사항이다.","교재 2권 p.40")
a(36,4,"금융기관보험대리점 등은 설명 사항 중 주요 보장 내용만 설명하면 나머지는 생략할 수 있다.","X","새로 만든 틀린 문장","금융위가 고시하는 바에 따라 각 호의 모든 사항을 설명해야 한다.","교재 2권 p.40")
a(39,1,"1년간의 금융소득이 4천만원을 초과하는 경우가 금융소득종합과세의 대상이다.","X","원본의 틀린 보기 그대로","기준은 2천만원 초과다.","교재 2권 p.97")
a(39,2,"금융소득종합과세 시 부동산 양도소득은 합산하지 않는다.","O","틀린 보기를 맞게 고침","양도소득은 합산하지 않는다.","교재 2권 p.97")
a(39,3,"금융소득종합과세는 원천징수 전의 금액을 기준으로 한다.","O","틀린 보기를 맞게 고침","원천징수 후 실수령액이 아니라 원천징수 전 금액이 기준이다.","교재 2권 p.97")
a(39,4,"금융소득이 종합과세 기준을 초과해도 다른 소득이 없으면 종합소득세 확정신고를 하지 않아도 된다.","X","'타 소득 유무를 떠나 신고 의무' → '다른 소득 없으면 안 해도 됨'","2천만원 초과 시 타 종합소득 유무와 관계없이 다음해 5월 확정신고 의무가 있다.","교재 2권 p.97")
# --- OX 뒤집기·단답→OX (시범안 재사용, 단답 2개는 O로 균형)
for v in V[10:25]:
    P.append(dict(of=v['of'],slot=0,q=v['q'],ans="O" if v['answer']==1 else "X",diff=v['diff'],exp=v['exp'],src=v['src']))
for p in P:
    if p['of']==65 and p['slot']==0: p.update(q="상호회사는 보험업법에 근거하여 설립할 수 있는 보험회사이다.",ans="O",diff="단답(상호회사) → 그대로 OX (O)",exp="주식회사는 상법, 상호회사는 보험업법에 근거해 설립한다.")
    if p['of']==74 and p['slot']==0: p.update(q="연금저축은 예금과 달리 이자소득이 아닌 연금소득 또는 기타소득으로 과세된다.",ans="O",diff="단답(기타소득) → 그대로 OX (O)",exp="교재 문장 그대로다.")
